package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringSubstitutor_ESTest_test02 extends StringSubstitutor_ESTest_scaffolding {

    /**
     * Verifies that {@link StringSubstitutor#replaceIn(StringBuilder)} performs in-place
     * substitution on a buffer that contains an escaped variable prefix.
     *
     * <p>The buffer is assembled so that it contains the escape sequence {@code "$$"} (an
     * escaped {@code '$'}, using the default escape character) immediately followed by the
     * variable prefix {@code "${"}. With the default syntax, {@code "$${"} is unescaped to a
     * literal {@code "${"}, while the trailing {@code "${}"} (an empty, unresolvable variable
     * name) is left untouched. Because at least one substitution/unescaping occurs,
     * {@code replaceIn} reports that the buffer was altered.</p>
     */
    @Test(timeout = 4000)
    public void replaceInUnescapesDollarPrefixAndReportsChange() throws Throwable {
        StringSubstitutor substitutor = new StringSubstitutor();

        // NOTE: StringBuilder.append() returns the same instance, so every append below
        // mutates this single buffer (there are no separate copies).
        StringBuilder buffer = new StringBuilder("}");

        // Append 4 NUL characters ('�') followed by a single '$'.
        char[] nullsThenDollar = new char[5];
        nullsThenDollar[4] = '$';
        buffer.append(nullsThenDollar);

        // Append the variable prefix twice and a closing brace, producing the escape
        // sequence "$$" (trailing '$' above + leading '$' here) ahead of a "${" prefix.
        buffer.append((CharSequence) "${");
        buffer.append("${");
        buffer.append("}");

        // Append the buffer's current contents onto itself, doubling the text.
        buffer.append((Object) buffer);

        boolean wasChanged = substitutor.replaceIn(buffer);

        // "$${" is unescaped to "${"; the empty-name variable "${}" stays as-is. The
        // doubled text yields the same resolved segment twice.
        assertEquals("}\\u0000\\u0000\\u0000\\u0000${${}}\\u0000\\u0000\\u0000\\u0000${${}", buffer.toString());
        assertTrue(wasChanged);
    }
}
